statement:
You're given an array that can hold numbers, strings, booleans — and other arrays, nested as deep as you like.

Count how many elements the array holds **in total, at every level**. An inner array counts as one element itself, and then everything inside it gets counted as well.

Return the total count. An empty array holds 0 elements.

**Function signature**

```js
function deepCount(arr) {
  // arr: an array (possibly containing nested arrays)
  // return a number
}
```

solution:
// CONTRACT for countElementDeep(element):
//     when this call returns, the returned value equals the count of
//     `element` itself plus everything nested anywhere inside it
//     (a plain non-array value counts as exactly 1).
const countElementDeep = (element) => {
    // Base case: a non-array element (number, string, boolean) counts as one.
    if (!Array.isArray(element)) return 1;

    // Process node: an inner array counts as one element itself...
    let totalCount = 1;

    // Recurse on neighbors: ...and then everything inside it counts too.
    for (const innerElement of element) {
        // The recursive leap of faith, one level down: this call has
        // the SAME contract — when it returns, its value counts
        // `innerElement` plus everything nested inside it. Trust it,
        // do not trace it. The 1 for this array + the guaranteed
        // counts of its contents = exactly this function's contract.
        totalCount += countElementDeep(innerElement);
    }

    return totalCount;
};

const deepCount = (arr) => {
    // The outermost array is the container we are counting inside of,
    // so it contributes 0 on its own -- only its contents count.
    let totalCount = 0;

    for (const element of arr) {
        // The recursive leap of faith: trust the contract. When this
        // call returns, its value is the complete count of `element`
        // and everything nested inside it, however deep. We do not
        // trace inside; we just add it to the running total.
        totalCount += countElementDeep(element);
    }

    return totalCount;
};

statement:
Farmer John's `N` cows are numbered `0` to `N - 1`, and cow `i` is standing at position `positions[i] = [x, y]` in the pasture (all positions are distinct).

Cows chat by mooing. `pairs[j] = [a, b]` means cows `a` and `b` moo back and forth with each other. Cows form **herds**: two cows belong to the same herd if they moo with each other directly, or are linked through a chain of mooing pairs. Every cow moos with at least one other cow.

Farmer John wants to build **one** rectangular fence, with sides parallel to the x- and y-axes, that contains every cow of **at least one entire herd** (cows from other herds may happen to end up inside too — that's fine). A cow standing exactly on the fence line counts as inside, and the rectangle is allowed to have zero width or zero height. A fence spanning width `w` and height `h` has perimeter `2 * (w + h)`.

Return the smallest perimeter Farmer John can get away with.

**Function signature**

```js
function minFencePerimeter(positions, pairs) {
  // positions: array of [x, y] integer pairs
  // pairs: array of [a, b] cow-number pairs
  // return a number
}
```

solution:
const buildGraph = (edges) => {
    const graph = {};

    for (const edge of edges) {
        const [nodeOne, nodeTwo] = edge;

        const nodeOneInGraph = graph.hasOwnProperty(nodeOne);
        const nodeTwoInGraph = graph.hasOwnProperty(nodeTwo);

        if (!nodeOneInGraph) graph[nodeOne] = [];
        if (!nodeTwoInGraph) graph[nodeTwo] = [];

        graph[nodeOne].push(nodeTwo);
        graph[nodeTwo].push(nodeOne);
    }

    return graph;
};

// CONTRACT for markHerdAsVisited(graph, cow, visited, herdCows):
//     when this call returns, `cow` and every cow connected to her
//     through any chain of friendships is in the visited set AND in
//     the `herdCows` list.
const markHerdAsVisited = (graph, cow, visited, herdCows) => {
    // Base case
    if (visited.has(cow)) return;

    // Process node
    visited.add(cow);
    herdCows.push(cow);

    // Recurse on neighbors
    const cowInGraph = graph.hasOwnProperty(cow);
    if (!cowInGraph) return;

    const neighbors = graph[cow];

    for (const neighbor of neighbors) {
        // The recursive leap of faith, one level down: this call has
        // the SAME contract — when it returns, `neighbor` and every
        // cow connected to `neighbor` is in visited and in `herdCows`.
        // Trust it, do not trace it. This function already put `cow`
        // into both, and each neighbor's contract covers the rest of
        // the herd — together, that is this function's full contract,
        // kept.
        markHerdAsVisited(graph, neighbor, visited, herdCows);
    }
};

const getHerdFencePerimeter = (positions, herdCows) => {
    let minX = Infinity;
    let maxX = -Infinity;
    let minY = Infinity;
    let maxY = -Infinity;

    for (const cow of herdCows) {
        const [x, y] = positions[cow];

        minX = Math.min(minX, x);
        maxX = Math.max(maxX, x);
        minY = Math.min(minY, y);
        maxY = Math.max(maxY, y);
    }

    // A cow standing exactly on the fence line still counts as inside,
    // so the tightest fence runs right through the outermost cows.
    const width = maxX - minX;
    const height = maxY - minY;

    return 2 * (width + height);
};

const minFencePerimeter = (positions, pairs) => {
    const graph = buildGraph(pairs);
    const numCows = positions.length;

    let smallestPerimeter = Infinity;
    const visited = new Set();

    for (let cow = 0; cow < numCows; cow++) {
        if (visited.has(cow)) continue;

        // Every cow we have not seen yet starts a brand new herd.
        const herdCows = [];
        // The recursive leap of faith: trust the contract. When this
        // call returns, `herdCows` holds the complete herd around
        // `cow`, and every one of those cows is in visited, so no
        // herd is ever built twice. We do not trace inside; we just
        // measure the finished herd's fence and keep the smallest.
        markHerdAsVisited(graph, cow, visited, herdCows);

        const herdPerimeter = getHerdFencePerimeter(positions, herdCows);
        smallestPerimeter = Math.min(smallestPerimeter, herdPerimeter);
    }

    return smallestPerimeter;
};

const GOLD = 'G';
const TRAP = 'T';
const WALL = '#';
const EXPLORER_START = 'P';

const getPositionString = (row, col) => `${row}, ${col}`;
const directions = [
    [0, 1],
    [1, 0],
    [0, -1],
    [-1, 0],
];

const isInBounds = (grid, row, col) => {
    const numRows = grid.length;
    const numCols = grid[0].length;

    const rowInBounds = row >= 0 && row < numRows;
    const colInBounds = col >= 0 && col < numCols;

    return rowInBounds && colInBounds;
};

const findStartPosition = (grid) => {
    for (let row = 0; row < grid.length; row++) {
        for (let col = 0; col < grid[row].length; col++) {
            if (grid[row][col] === EXPLORER_START) return [row, col];
        }
    }
};

const feelsDraft = (grid, row, col) => {
    for (const direction of directions) {
        const [rowChange, colChange] = direction;

        const neighborRow = row + rowChange;
        const neighborCol = col + colChange;

        if (!isInBounds(grid, neighborRow, neighborCol)) continue;

        if (grid[neighborRow][neighborCol] === TRAP) return true;
    }

    return false;
};

// CONTRACT for countGoldFromPosition(grid, row, col, visited):
//     when this call returns, every safe square the explorer can
//     reach from (`row`, `col`) that was not already in the visited
//     set is now in it, and the returned value equals the gold
//     sitting on those newly added squares.
const countGoldFromPosition = (grid, row, col, visited) => {
    // Base cases
    if (!isInBounds(grid, row, col)) return 0;

    const curPositionString = getPositionString(row, col);
    if (visited.has(curPositionString)) return 0;

    if (grid[row][col] === WALL) return 0;

    // Process node
    visited.add(curPositionString);

    let goldCollected = grid[row][col] === GOLD ? 1 : 0;

    // A draft means a trap could hide on ANY neighbor she has not stood on,
    // so she grabs this square's gold and only retraces her steps back out.
    if (feelsDraft(grid, row, col)) return goldCollected;

    // Recurse on neighbors
    // No draft here means every non-wall neighbor is guaranteed trap-free.
    for (const direction of directions) {
        const [rowChange, colChange] = direction;

        const newRow = row + rowChange;
        const newCol = col + colChange;

        // The recursive leap of faith, one level down: this call has
        // the SAME contract — when it returns, every new safe square
        // reachable from this neighbor is in visited, and the call
        // returns the gold on exactly those squares. Trust it, do not
        // trace it. This square's own gold + each neighbor's guaranteed
        // gold = exactly this function's contract.
        goldCollected += countGoldFromPosition(grid, newRow, newCol, visited);
    }

    return goldCollected;
};

const collectSafeGold = (grid) => {
    const [startRow, startCol] = findStartPosition(grid);

    const visited = new Set();

    // The recursive leap of faith: trust the contract. When this
    // call returns, its value is ALL the gold the explorer can safely
    // collect from her starting square. We do not trace inside; we
    // just return that number as the answer.
    return countGoldFromPosition(grid, startRow, startCol, visited);
};
